INSERT INTO questionnaires (language, questionnaire) VALUES ('SR', '{"info":[{"position":1,"settings":{"RichText":"<h1>Dobrodošli</h1><p>Menopauza nije kraj, već novi početak koji zaslužuje jasne odgovore i pravu podršku.</p><p>Naš upitnik je kreiran da vam pomogne da razumete kroz koju fazu prolazite i pruži vam naučno zasnovane smernice za očuvanje vašeg zdravlja.</p><p>Niste same na ovom putu. Tu smo da vam unesemo mir, pružimo jasnoću i personalizovanu podršku u svakom koraku.</p><p>Hajde da počnemo.</p>"},"QuestionType":"intro","DataPointName":"WelcomeMessage"},{"position":2,"settings":{"QuestionText":"Kako se zovete?","QuestionHelper":"Molimo vas unesite vaše ime."},"QuestionType":"first_name","DataPointName":"FirstName"},{"position":3,"settings":{"fields":[{"type":"numeric","label":"Godina rođenja","mandatory":true,"measurement":"Godina","error_message":"Ovo polje je obavezno."}],"QuestionText":"Koja je vaša godina rođenja?","QuestionHelper":"Molimo vas unesite godinu u kojoj ste rođeni."},"QuestionType":"custom_form","DataPointName":"BirthYear"},{"position":4,"settings":{"fields":[{"type":"numeric","label":"Visina","mandatory":true,"measurement":"cm","error_message":"Ovo polje je obavezno."}],"QuestionText":"Kolika je vaša visina?","QuestionHelper":"Molimo vas unesite vašu visinu u centimetrima."},"QuestionType":"custom_form","DataPointName":"Height"},{"position":5,"settings":{"fields":[{"type":"numeric","label":"Težina","mandatory":true,"measurement":"kg","error_message":"Ovo polje je obavezno."}],"QuestionText":"Kolika je vaša trenutna težina?","QuestionHelper":"Molimo vas unesite vašu težinu u kilogramima."},"QuestionType":"custom_form","DataPointName":"Weight"},{"position":6,"settings":{"options":[{"OptionText":"Imam redovne menstruacije."},{"OptionText":"Imam redovne menstruacije, ali su se promenile po količini obilnosti."},{"OptionText":"I Imam neredovne menstruacije i ponekad prođe više meseci bez menstruacije."},{"OptionText":"Nisam imala menstruaciju nekoliko meseci, ali manje od godinu dana."},{"OptionText":"Nisam imala menstruaciju godinu dana ili duže."}],"QuestionText":"Recite nam više o Vašem ciklusu?","QuestionHelper":"Izaberite opciju koja vam najbolje odgovara."},"QuestionType":"single_option","DataPointName":"Menstrual Status"},{"position":7,"settings":{"options":[{"OptionText":"Nikada nisam koristila hormonsku supstitucionu terapiju."},{"OptionText":"Trenutno koristim hormonsku supstitucionu terapiju."},{"OptionText":"Koristila sam hormonsku supstitucionu terapiju u prošlosti."}],"QuestionText":"Da li koristite ili ste koristili hormonsku supstitucionu terapiju?","QuestionHelper":"Izaberite opciju koja najbolje opisuje vaše iskustvo."},"QuestionType":"single_option","DataPointName":"HRT Treatment History"},{"position":8,"settings":{"options":[{"OptionText":"Nemam valunge.","OptionValue":1},{"OptionText":"Povremeno, nekoliko puta mesečno.","OptionValue":2},{"OptionText":"Često, više puta nedeljno.","OptionValue":3},{"OptionText":"Svakodnevno ili stalno tokom dana i noći.","OptionValue":4}],"QuestionText":"Koliko često imate valunge?","QuestionHelper":"Izaberite opciju koja najbolje opisuje koliko često imate valunge?"},"QuestionType":"scale","DataPointName":"Hot Flushes"},{"position":9,"settings":{"options":[{"OptionText":"Nemam noćno znojenje.","OptionValue":1},{"OptionText":"Povremeno, nekoliko puta mesečno.","OptionValue":2},{"OptionText":"Često, više puta nedeljno.","OptionValue":3},{"OptionText":"Stalno, remeti mi san skoro svake noći.","OptionValue":4}],"QuestionText":"Koliko često imate noćno znojenje?","QuestionHelper":"Izaberite opciju koja najbolje opisuje koliko često imate noćno znojenje."},"QuestionType":"scale","DataPointName":"Night Sweats"},{"position":10,"settings":{"options":[{"OptionText":"Nemam palpitacije.","OptionValue":1},{"OptionText":"Povremeno, nekoliko puta mesečno.","OptionValue":2},{"OptionText":"Često, više puta nedeljno.","OptionValue":3},{"OptionText":"Teške, skoro sva